func (v PaginationValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"augmented":   basetypes.BoolType{},
		"count":       basetypes.Int64Type{},
		"page":        basetypes.Int64Type{},
		"sort_method": basetypes.StringType{},
		"sort_order":  basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"augmented":   v.Augmented,
			"count":       v.Count,
			"page":        v.Page,
			"sort_method": v.SortMethod,
			"sort_order":  v.SortOrder,
		})

	return objVal, diags
}

